func repGTCanonHeader(t repGTObjType, size int64) []byte {
	b := make([]byte, 0, 24)
	b = append(b, t.String()...)
	b = append(b, ' ')
	b = strconv.AppendInt(b, size, 10)
	return append(b, 0)
}

// Port source: zeros3-z3/gitz3/objects.go
