// skipString advances over a string and returns its length, keeping up to keep bytes.
func (b *repGGreader) skipString(lim repGGLimits, keep int) (string, error) {
	n, err := b.u64()
	if err != nil {
		return "", err
	}
	if n > uint64(lim.MaxString) {
		return "", fmt.Errorf("%w: string of %d bytes", repGGErrLimit, n)
	}
	if int64(n) > b.limit-b.pos {
		return "", fmt.Errorf("%w: string of %d bytes past the bound", repGGErrFormat, n)
	}
	if int(n) <= keep {
		s, err := b.need(int64(n))
		return string(s), err
	}
	b.pos += int64(n)
	return "", nil
}

// Port source: zeros3-z3/ggufz3/gguf.go
// value consumes one value of type t; scalars fill kv.Uint, strings kv.Str, arrays kv.ElemType/Count.
func (b *repGGreader) value(t uint32, kv *repGGKV, lim repGGLimits, depth int) error {
	if n, ok := repGGscalarSize[t]; ok {
		s, err := b.need(n)
		if err != nil {
			return err
		}
		if depth == 0 {
			var buf [8]byte
			copy(buf[:], s)
			kv.Uint = binary.LittleEndian.Uint64(buf[:])
		}
		return nil
	}
	switch t {
	case repGGTString:
		s, err := b.skipString(lim, 256)
		if depth == 0 {
			kv.Str = s
		}
		return err
	case repGGTArray:
		if depth >= lim.MaxDepth {
			return fmt.Errorf("%w: array nesting", repGGErrLimit)
		}
		et, err := b.u32()
		if err != nil {
			return err
		}
		cnt, err := b.u64()
		if err != nil {
			return err
		}
		if depth == 0 {
			kv.ElemType, kv.Count = et, cnt
		}
		if n, ok := repGGscalarSize[et]; ok {
			// the count must fit the remaining bound before anything is walked or allocated
			if cnt > uint64(math.MaxInt64)/uint64(n) || int64(cnt)*n > b.limit-b.pos {
				return fmt.Errorf("%w: array of %d x %d bytes past the bound", repGGErrFormat, cnt, n)
			}
			b.pos += int64(cnt) * n
			return nil
		}
		if et != repGGTString && et != repGGTArray {
			return fmt.Errorf("%w: array element type %d", repGGErrFormat, et)
		}
		// every string/array element costs at least 8 bytes
		if cnt > uint64(b.limit-b.pos)/8 {
			return fmt.Errorf("%w: array of %d elements past the bound", repGGErrFormat, cnt)
		}
		var scratch repGGKV
		for i := uint64(0); i < cnt; i++ {
			if err := b.value(et, &scratch, lim, depth+1); err != nil {
				return err
			}
		}
		return nil
	}
	return fmt.Errorf("%w: value type %d", repGGErrFormat, t)
}

// Port source: zeros3-z3/ggufz3/gguf.go
// Parse reads the structure of a GGUF file of the given size. It reads only the header
// (bounded by Limits.MaxMeta), never tensor payloads.
func repGGParse(r io.ReaderAt, size int64, lim repGGLimits) (*repGGFile, error) {
	lim = lim.norm()
	if size < 24 {
		return nil, fmt.Errorf("%w: %d bytes", repGGErrFormat, size)
	}
	b := &repGGreader{r: r, limit: min(size, lim.MaxMeta)}
	m, err := b.need(4)
	if err != nil || string(m) != "GGUF" {
		return nil, fmt.Errorf("%w: bad magic", repGGErrFormat)
	}
	f := &repGGFile{Size: size, Alignment: 32}
	if f.Version, err = b.u32(); err != nil {
		return nil, err
	}
	if f.Version != 2 && f.Version != 3 {
		return nil, fmt.Errorf("%w: GGUF version %d", repGGErrUnsupported, f.Version)
	}
	nt, err := b.u64()
	if err != nil {
		return nil, err
	}
	nkv, err := b.u64()
	if err != nil {
		return nil, err
	}
	if nt > uint64(lim.MaxTensors) || nkv > uint64(lim.MaxKV) {
		return nil, fmt.Errorf("%w: %d tensors, %d key/values", repGGErrLimit, nt, nkv)
	}
	// every entry costs at least 12 bytes, so the counts are checked against the bound
	// before anything is allocated
	if nkv > uint64(b.limit-b.pos)/12 || nt > uint64(b.limit-b.pos)/24 {
		return nil, fmt.Errorf("%w: counts exceed the header bound", repGGErrFormat)
	}
	f.KVs = make([]repGGKV, 0, nkv)
	seen := make(map[string]bool, nkv)
	for i := uint64(0); i < nkv; i++ {
		var kv repGGKV
		kv.Off = b.pos
		if kv.Key, err = b.str(1 << 12); err != nil {
			return nil, err
		}
		if kv.Key == "" || seen[kv.Key] {
			return nil, fmt.Errorf("%w: empty or duplicate key %q", repGGErrFormat, kv.Key)
		}
		seen[kv.Key] = true
		if kv.Type, err = b.u32(); err != nil {
			return nil, err
		}
		if err = b.value(kv.Type, &kv, lim, 0); err != nil {
			return nil, err
		}
		kv.End = b.pos
		f.KVs = append(f.KVs, kv)
	}
	if kv, ok := f.Lookup("general.alignment"); ok {
		if kv.Type != repGGTUint32 || kv.Uint == 0 || kv.Uint&(kv.Uint-1) != 0 || kv.Uint > 1<<20 {
			return nil, fmt.Errorf("%w: general.alignment %d", repGGErrFormat, kv.Uint)
		}
		f.Alignment = int64(kv.Uint)
	}
	f.Tensors = make([]repGGTensor, 0, nt)
	names := make(map[string]bool, nt)
	for i := uint64(0); i < nt; i++ {
		t := repGGTensor{Index: int(i)}
		if t.Name, err = b.str(1 << 12); err != nil {
			return nil, err
		}
		if names[t.Name] {
			return nil, fmt.Errorf("%w: duplicate tensor name %q", repGGErrFormat, t.Name)
		}
		names[t.Name] = true
		nd, err := b.u32()
		if err != nil {
			return nil, err
		}
		if nd == 0 || nd > 4 {
			return nil, fmt.Errorf("%w: %d dimensions", repGGErrFormat, nd)
		}
		t.Dims = make([]uint64, nd)
		for j := range t.Dims {
			if t.Dims[j], err = b.u64(); err != nil {
				return nil, err
			}
		}
		if t.Type, err = b.u32(); err != nil {
			return nil, err
		}
		if t.RelOffset, err = b.u64(); err != nil {
			return nil, err
		}
		f.Tensors = append(f.Tensors, t)
	}
	f.InfoEnd = b.pos
	f.DataStart = (f.InfoEnd + f.Alignment - 1) / f.Alignment * f.Alignment
	if f.DataStart > size || f.DataStart < f.InfoEnd {
		return nil, fmt.Errorf("%w: data area starts at %d, file has %d bytes", repGGErrFormat, f.DataStart, size)
	}
	f.DataEnd = f.DataStart
	for i := range f.Tensors {
		t := &f.Tensors[i]
		n, err := repGGNBytes(t.Type, t.Dims)
		if err != nil {
			return nil, fmt.Errorf("tensor %q: %w", t.Name, err)
		}
		if t.RelOffset%uint64(f.Alignment) != 0 || t.RelOffset > uint64(size-f.DataStart) || uint64(n) > uint64(size-f.DataStart)-t.RelOffset {
			return nil, fmt.Errorf("%w: tensor %q [%d,+%d) is unaligned or outside the %d-byte data area", repGGErrFormat, t.Name, t.RelOffset, n, size-f.DataStart)
		}
		t.Begin = f.DataStart + int64(t.RelOffset)
		t.End = t.Begin + n
		f.DataEnd = max(f.DataEnd, t.End)
	}
	f.Order = make([]int, len(f.Tensors))
	for i := range f.Order {
		f.Order[i] = i
	}
	sort.SliceStable(f.Order, func(a, c int) bool { return f.Tensors[f.Order[a]].Begin < f.Tensors[f.Order[c]].Begin })
	for k := 1; k < len(f.Order); k++ {
		p, c := &f.Tensors[f.Order[k-1]], &f.Tensors[f.Order[k]]
		if p.Size() > 0 && c.Size() > 0 && p.End > c.Begin {
			return nil, fmt.Errorf("%w: tensors %q and %q overlap", repGGErrFormat, p.Name, c.Name)
		}
	}
	return f, nil
}

// Port source: zeros3-z3/ggufz3/gguf.go
// Segment is one piece of the exact file layout, in file order.
type repGGSegment struct {
	Begin, End int64
	Tensor     int // index into File.Tensors, or -1 for header / alignment gap / tail
	Kind       string
}

// Port source: zeros3-z3/ggufz3/gguf.go
// Segments tiles [0,Size) exactly: the header (magic through the padding that precedes the
// data area), each tensor, the gaps between tensors and the tail after the last one.
func (f *repGGFile) Segments() []repGGSegment {
	segs := []repGGSegment{{0, f.DataStart, -1, "header"}}
	pos := f.DataStart
	for _, i := range f.Order {
		t := &f.Tensors[i]
		if t.Size() == 0 {
			continue
		}
		if t.Begin > pos {
			segs = append(segs, repGGSegment{pos, t.Begin, -1, "gap"})
		}
		segs = append(segs, repGGSegment{t.Begin, t.End, i, "tensor"})
		pos = t.End
	}
	if pos < f.Size {
		segs = append(segs, repGGSegment{pos, f.Size, -1, "tail"})
	}
	return segs
}

// ---- Q9 DRAFT ONLY: model recipe adapter, framework names translated ----------
// Mechanically extracted from zeros3-z3 codec sources; see provenance manifest.

// Port source: zeros3-z3/repz3/kinds/model.go
// KindModel (Z3-29 laboratory kind 8) is a model artifact - a Safetensors, GGUF or torch ZIP file -
// as an exact list of operations over ordinary content-addressed members, with no format
// knowledge in the decoder: the encoder's parser found the framing and tensor spans, the decoder
// only concatenates and applies residuals. The recipe is
//
//	version (1) | uvarint n ops | ops | uvarint n names | names
//	COPY      0x00 uvarint m                              emit member m (a component, or a child's output)
//	XORPLANES 0x01 uvarint base, uvarint res, uvarint w, uvarint e
//	                                                      emit base XOR unplane(res); |base| == |res|
//	PLANES    0x02 uvarint res, uvarint w, uvarint e      emit unplane(res)
//	name      uvarint op index | uvarint len | bytes      a tensor-name hint for point reads
//
// A residual component is a sequence of chunks of e elements of w bytes; inside a chunk the bytes
// are separated by position within the element (all byte 0s, then all byte 1s, ...), the layout
// that DEFLATE under the ordinary pack rule compresses (Z3-10 T0) and that a sequential decoder
// can verify with one SHA-256 pass. For GGUF an "element" is one quantisation block of w bytes. The
// base member is exact bytes named by their SHA-256: a STORED component, or a DERIVED member whose
// child is another KindModel representation of those bytes (a bounded chain through the
// contract's depth limit). Nothing here names a bucket, key or version.
const (
	repMDmodelVer           = 1
	repMDopCopy        byte = 0
	repMDopXORPlanes   byte = 1
	repMDopPlanes      byte = 2
	repMDmaxOps             = 1 << 16
	repMDmaxModelW          = 4096
	repMDmaxChunkBytes      = 16 << 20 // one residual chunk (E elements of W bytes): the only decode-side allocation unit
)

// Port source: zeros3-z3/repz3/kinds/model.go
type repMDmodelOp struct {
	Tag          byte
	M, Base, Res int
	W, E         int
	Size         int64
}

// Port source: zeros3-z3/repz3/kinds/model.go
type repMDmodelRecipe struct {
	Ops   []repMDmodelOp
	Names []repMDmodelName
}

// Port source: zeros3-z3/repz3/kinds/model.go
type repMDmodelName struct {
	Op   int
	Name string
}

// Port source: zeros3-z3/repz3/kinds/model.go
func repMDuv(b []byte) (uint64, []byte, bool) {
	v, n := binary.Uvarint(b)
	if n <= 0 {
		return 0, b, false
	}
	return v, b[n:], true
}

// Port source: zeros3-z3/repz3/kinds/model.go
func repMDparseModelRecipe(rep *repObject) (*repMDmodelRecipe, error) {
	b := rep.Recipe
	bad := func(f string, a ...any) (*repMDmodelRecipe, error) {
		return nil, fmt.Errorf("%w: model recipe: %s", errRepCorrupt, fmt.Sprintf(f, a...))
	}
	if len(b) < 1 || b[0] != repMDmodelVer {
		return bad("version")
	}
	b = b[1:]
	n, b, ok := repMDuv(b)
	if !ok || n > repMDmaxOps || n > uint64(len(b)) {
		return bad("op count")
	}
	r := &repMDmodelRecipe{Ops: make([]repMDmodelOp, 0, n)}
	nm := len(rep.Members)
	var total int64
	size := func(m int) int64 { return rep.Members[m].Size }
	for i := uint64(0); i < n; i++ {
		if len(b) < 1 {
			return bad("truncated op %d", i)
		}
		op := repMDmodelOp{Tag: b[0]}
		b = b[1:]
		get := func(max int) (int, bool) {
			var v uint64
			v, b, ok = repMDuv(b)
			if !ok || v >= uint64(max) {
				return 0, false
			}
			return int(v), true
		}
		switch op.Tag {
		case repMDopCopy:
			if op.M, ok = get(nm); !ok {
				return bad("op %d member", i)
			}
			op.Size = size(op.M)
		case repMDopXORPlanes, repMDopPlanes:
			if op.Tag == repMDopXORPlanes {
				if op.Base, ok = get(nm); !ok {
					return bad("op %d base", i)
				}
			}
			if op.Res, ok = get(nm); !ok {
				return bad("op %d residual", i)
			}
			if op.W, ok = get(repMDmaxModelW + 1); !ok || op.W < 1 {
				return bad("op %d width", i)
			}
			if op.E, ok = get(1 << 28); !ok || op.E < 1 || int64(op.E)*int64(op.W) > repMDmaxChunkBytes {
				return bad("op %d chunk", i)
			}
			op.Size = size(op.Res)
			if op.Size%int64(op.W) != 0 {
				return bad("op %d residual %d bytes is not a multiple of %d", i, op.Size, op.W)
			}
			if op.Tag == repMDopXORPlanes && size(op.Base) != op.Size {
				return bad("op %d base is %d bytes, residual %d", i, size(op.Base), op.Size)
			}
			if rep.Members[op.Res].Role != repStored {
				return bad("op %d residual is not a component", i)
			}
		default:
			return bad("op %d tag %d", i, op.Tag)
		}
		if total > 1<<62-op.Size {
			return bad("size overflow")
		}
		total += op.Size
		r.Ops = append(r.Ops, op)
	}
	if total != rep.Size {
		return bad("ops produce %d bytes, representation declares %d", total, rep.Size)
	}
	nn, b, ok := repMDuv(b)
	if !ok || nn > n {
		return bad("name count")
	}
	for i := uint64(0); i < nn; i++ {
		var o, l uint64
		if o, b, ok = repMDuv(b); !ok || o >= n {
			return bad("name %d op", i)
		}
		if l, b, ok = repMDuv(b); !ok || l > 4096 || l > uint64(len(b)) {
			return bad("name %d length", i)
		}
		r.Names = append(r.Names, repMDmodelName{int(o), string(b[:l])})
		b = b[l:]
	}
	if len(b) != 0 {
		return bad("%d trailing bytes", len(b))
	}
	return r, nil
}

// Port source: zeros3-z3/repz3/kinds/model.go
type repMDmodelDecoder struct{}

// Port source: zeros3-z3/repz3/kinds/model.go
// Expand: every component is a listed member, so there is nothing named only inside another object.
func (repMDmodelDecoder) Expand(c *repCall, emit func([32]byte)) error {
	_, err := repMDparseModelRecipe(c.Rep)
	return err
}

// Port source: zeros3-z3/repz3/kinds/model.go
func (repMDmodelDecoder) Decode(c *repCall) error {
	r, err := repMDparseModelRecipe(c.Rep)
	if err != nil {
		return err
	}
	if err := c.decodeWork().step(int64(len(r.Ops))); err != nil {
		return err
	}

	var bufs [3][]byte // residual, base and output chunks, reused by every op
	for i := range r.Ops {
		op := &r.Ops[i]
		if op.Tag == repMDopCopy {
			if err := c.writeMemberAt(op.M, c.W); err != nil {
				return fmt.Errorf("op %d: %w", i, err)
			}
			continue
		}
		if err := repMDapplyResidual(c, op, c.W, &bufs); err != nil {
			return fmt.Errorf("op %d: %w", i, err)
		}
	}
	return nil
}

// Port source: zeros3-z3/repz3/kinds/model.go
// memberStream reads member m sequentially; on EOF the length and SHA-256 are enforced.
func repMDmemberStream(c *repCall, m int) io.ReadCloser {
	mem := &c.Rep.Members[m]
	if mem.Role == repStored {
		return &repMDstoredReader{src: c.env.Src, id: mem.SHA, size: mem.Size, h: sha256.New()}
	}
	pr, pw := io.Pipe()
	go func() { pw.CloseWithError(c.writeMemberAt(m, pw)) }()
	return pr
}

// Port source: zeros3-z3/repz3/kinds/model.go
type repMDstoredReader struct {
	src  repSource
	id   [32]byte
	size int64
	off  int64
	h    interface {
		io.Writer
		Sum([]byte) []byte
	}
	checked bool
}

// Port source: zeros3-z3/repz3/kinds/model.go
func (s *repMDstoredReader) Close() error { return nil }

// Port source: zeros3-z3/repz3/kinds/model.go
func (s *repMDstoredReader) Read(p []byte) (int, error) {
	if !s.checked {
		got, err := s.src.Size(s.id)
		if err != nil {
			return 0, err
		}
		if got != s.size {
			return 0, fmt.Errorf("%w: %x is %d bytes, recipe says %d", errRepMismatch, s.id[:6], got, s.size)
		}
		s.checked = true
	}
	if s.off == s.size {
		var sum [32]byte
		s.h.Sum(sum[:0])
		if sum != s.id {
			return 0, fmt.Errorf("%w: %x bytes do not hash to their address", errRepMismatch, s.id[:6])
		}
		return 0, io.EOF
	}
	n := int(min(int64(len(p)), s.size-s.off))
	got, err := s.src.ReadAt(s.id, p[:n], s.off)
	if got != n {
		if err == nil || err == io.EOF {
			err = errRepShort
		}
		return 0, err
	}
	s.h.Write(p[:n])
	s.off += int64(n)
	return n, nil
}

// Port source: zeros3-z3/repz3/kinds/model.go
func repMDapplyResidual(c *repCall, op *repMDmodelOp, w io.Writer, bufs *[3][]byte) error {
	res := repMDmemberStream(c, op.Res)
	defer res.Close()
	var base io.ReadCloser
	if op.Tag == repMDopXORPlanes {
		base = repMDmemberStream(c, op.Base)
		defer base.Close()
	}
	chunk := int64(op.E) * int64(op.W)
	n0 := int(min(chunk, op.Size))
	for i := range bufs {
		if cap(bufs[i]) < n0 {
			bufs[i] = make([]byte, n0)
		}
	}
	rbuf, bbuf, out := bufs[0][:n0], bufs[1][:n0], bufs[2][:n0]
	for done := int64(0); done < op.Size; {
		n := min(chunk, op.Size-done)
		if _, err := io.ReadFull(res, rbuf[:n]); err != nil {
			return err
		}
		repMDunplane(out[:n], rbuf[:n], op.W)
		if base != nil {
			if _, err := io.ReadFull(base, bbuf[:n]); err != nil {
				return err
			}
			for i := int64(0); i < n; i++ {
				out[i] ^= bbuf[i]
			}
		}
		if got, err := w.Write(out[:n]); err != nil {
			return err
		} else if int64(got) != n {
			return io.ErrShortWrite
		}
		done += n
	}
	// both streams must now be exactly at their verified end
	var one [1]byte
	if _, err := res.Read(one[:]); err != io.EOF {
		return fmt.Errorf("%w: residual has trailing data", errRepMismatch)
	}
	if base != nil {
		if _, err := base.Read(one[:]); err != io.EOF {
			if err == nil {
				err = fmt.Errorf("%w: base has trailing data", errRepMismatch)
			}
			return err
		}
	}
	return nil
}

// Port source: zeros3-z3/repz3/kinds/model.go
// unplane writes the interleaved form of one chunk (len(src) a multiple of w): src holds the
// w planes of e = len/w elements back to back.
func repMDunplane(dst, src []byte, w int) {
	e := len(src) / w
	if w == 1 {
		copy(dst, src)
		return
	}
	for p := 0; p < w; p++ {
		col := src[p*e : (p+1)*e]
		for i, v := range col {
			dst[i*w+p] = v
		}
	}
}

// Port source: zeros3-z3/repz3/kinds/model.go
// PlaneChunks is the encoder side of the residual layout: it separates b (a multiple of w long)
// chunk by chunk, e elements per chunk.
func repMDPlaneChunks(b []byte, w, e int) []byte {
	out := make([]byte, len(b))
	if w == 1 {
		copy(out, b)
		return out
	}
	step := w * e
	for off := 0; off < len(b); off += step {
		n := min(step, len(b)-off)
		ne := n / w
		src := b[off : off+n]
		dst := out[off : off+n]
		for p := 0; p < w; p++ {
			col := dst[p*ne : (p+1)*ne]
			for i := range col {
				col[i] = src[i*w+p]
			}
		}
	}
	return out
}

// Port source: zeros3-z3/repz3/kinds/model.go
// ModelOp is one operation in a recipe under construction.
type repMDModelOp struct {
	Tag          byte
	M, Base, Res int
	W, E         int
	Name         string
}

// Port source: zeros3-z3/repz3/kinds/model.go
// BuildModelRecipe serialises ops (member indexes refer to the representation's Members).
func repMDBuildModelRecipe(ops []repMDModelOp) []byte {
	b := []byte{repMDmodelVer}
	b = binary.AppendUvarint(b, uint64(len(ops)))
	for _, o := range ops {
		b = append(b, o.Tag)
		switch o.Tag {
		case repMDopCopy:
			b = binary.AppendUvarint(b, uint64(o.M))
		case repMDopXORPlanes:
			b = binary.AppendUvarint(b, uint64(o.Base))
			fallthrough
		case repMDopPlanes:
			b = binary.AppendUvarint(b, uint64(o.Res))
			b = binary.AppendUvarint(b, uint64(o.W))
			b = binary.AppendUvarint(b, uint64(o.E))
		}
	}
	nn := 0
	for _, o := range ops {
		if o.Name != "" {
			nn++
		}
	}
	b = binary.AppendUvarint(b, uint64(nn))
	for i, o := range ops {
		if o.Name != "" {
			b = binary.AppendUvarint(b, uint64(i))
			b = binary.AppendUvarint(b, uint64(len(o.Name)))
			b = append(b, o.Name...)
		}
	}
	return b
}

// Port source: zeros3-z3/repz3/kinds/model.go
var repMDerrRange = errors.New("kinds: range outside the representation")

// Port source: zeros3-z3/repz3/kinds/model.go
// ModelNames lists the tensor names the recipe carries, with the byte offset and length each op
// produces (the point-read index).
func repMDModelNames(c *repCall) (map[string][2]int64, error) {
	r, err := repMDparseModelRecipe(c.Rep)
	if err != nil {
		return nil, err
	}
	offs := make([]int64, len(r.Ops)+1)
	for i, op := range r.Ops {
		offs[i+1] = offs[i] + op.Size
	}
	out := map[string][2]int64{}
	for _, n := range r.Names {
		if _, exists := out[n.Name]; exists {
			return nil, errRepAmbiguous
		}
		out[n.Name] = [2]int64{offs[n.Op], r.Ops[n.Op].Size}
	}
	return out, nil
}

// Port source: zeros3-z3/repz3/kinds/model.go
// ReadModelRange returns bytes [off, off+n) of an opened KindModel representation touching only the
// ops (and chunks, and base-chain members) that overlap it. Component bytes are length-checked
// but not hash-verified on this path (a hash needs a sequential pass); the whole-file path
// verifies everything.
func repMDReadModelRange(c *repCall, off, n int64) ([]byte, error) {
	if c.decodeWork().metadata.Add(int64(len(c.Rep.Recipe))) > 64<<20 {
		return nil, fmt.Errorf("%w: aggregate range metadata", errRepLimit)
	}
	if n > 64<<20 {
		return nil, errRepLimit
	}
	if c.Rep.Kind != repKindModel {
		return nil, errors.New("kinds: not a model representation")
	}
	if off < 0 || n < 0 || off > c.Rep.Size || n > c.Rep.Size-off {
		return nil, repMDerrRange
	}
	r, err := repMDparseModelRecipe(c.Rep)
	if err != nil {
		return nil, err
	}
	if err := c.decodeWork().step(int64(len(r.Ops))); err != nil {
		return nil, err
	}

	if err := c.decodeWork().reserveBytes(n); err != nil {
		return nil, err
	}
	out := make([]byte, 0, n)
	pos := int64(0)
	for i := range r.Ops {
		op := &r.Ops[i]
		lo, hi := max(off, pos), min(off+n, pos+op.Size)
		if lo < hi {
			part, err := repMDreadOp(c, op, lo-pos, hi-lo)
			if err != nil {
				return nil, err
			}
			out = append(out, part...)
		}
		pos += op.Size
	}
	return out, nil
}

// Port source: zeros3-z3/repz3/kinds/model.go
func repMDreadMemberRange(c *repCall, m int, off, n int64) ([]byte, error) {
	mem := &c.Rep.Members[m]
	if mem.Role == repStored {
		buf := make([]byte, n)
		got, err := c.env.Src.ReadAt(mem.SHA, buf, off)
		if int64(got) != n {
			if err == nil || err == io.EOF {
				err = errRepShort
			}
			return nil, err
		}
		return buf, nil
	}
	if len(mem.Frame.Prefix) != 0 || mem.Frame.Zeros != 0 {
		return nil, errRepUnsupported
	}
	ch, err := c.child(m)
	if err != nil {
		return nil, err
	}
	return repMDReadModelRange(ch, off, n)
}

// Port source: zeros3-z3/repz3/kinds/model.go
func repMDreadOp(c *repCall, op *repMDmodelOp, off, n int64) ([]byte, error) {
	if op.Tag == repMDopCopy {
		return repMDreadMemberRange(c, op.M, off, n)
	}
	w, e := int64(op.W), int64(op.E)
	chunk := w * e
	out := make([]byte, 0, n)
	for cs := off - off%chunk; cs < off+n; cs += chunk {
		cn := min(chunk, op.Size-cs)
		ne := cn / w
		lo, hi := max(off, cs), min(off+n, cs+cn)
		// elements [ea, eb) of this chunk cover the request; each plane is read for those only
		ea, eb := (lo-cs)/w, (hi-cs+w-1)/w
		plain := make([]byte, (eb-ea)*w)
		for p := int64(0); p < w; p++ {
			pl, err := repMDreadMemberRange(c, op.Res, cs+p*ne+ea, eb-ea)
			if err != nil {
				return nil, err
			}
			for i, v := range pl {
				plain[int64(i)*w+p] = v
			}
		}
		if op.Tag == repMDopXORPlanes {
			bb, err := repMDreadMemberRange(c, op.Base, cs+ea*w, (eb-ea)*w)
			if err != nil {
				return nil, err
			}
			for i := range plain {
				plain[i] ^= bb[i]
			}
		}
		out = append(out, plain[lo-cs-ea*w:hi-cs-ea*w]...)
	}
	return out, nil
}

// ---- Bounded streaming model analysis -------------------------
const repModelWindow = 256 << 10
const repModelDigestHint = "tensor-output-sha256/"

type repModelSpan struct {
	begin, end          int64
	name, format, dtype string
	shape               []uint64
	width               int
}

// The bounded ReaderAt protobuf cursor is adapted from z3/semcore/onnx.go.
// It visits inline tensor metadata while skipping opaque bytes and payloads.
type repONNXField struct {
	num, wire uint64
	value     uint64
	start     int64
	end       int64
}

type repONNXReader struct {
	src        io.ReaderAt
	window     [4096]byte
	base, size int64
	budget     int
}

func (r *repONNXReader) varint(pos *int64, end int64) (uint64, error) {
	var value uint64
	for shift := uint(0); shift < 70 && *pos < end; shift += 7 {
		if *pos < r.base || *pos >= r.base+r.size {
			n := min(int64(len(r.window)), end-*pos)
			if err := repReadFullAt(r.src, r.window[:n], *pos); err != nil {
				return 0, err
			}
			r.base, r.size = *pos, n
		}
		b := r.window[*pos-r.base]
		*pos++
		if shift == 63 && b > 1 {
			break
		}
		value |= uint64(b&127) << shift
		if b < 128 {
			return value, nil
		}
	}
	return 0, repCorrupt("invalid ONNX varint")
}

func (r *repONNXReader) fields(pos, end int64, visit func(repONNXField) error) error {
	for pos < end {
		if r.budget == 0 {
			return errRepLimit
		}
		r.budget--
		tag, err := r.varint(&pos, end)
		if err != nil {
			return err
		}
		f := repONNXField{num: tag >> 3, wire: tag & 7}
		if f.num == 0 || f.num >= 1<<29 {
			return repCorrupt("invalid ONNX field")
		}
		var size uint64
		switch f.wire {
		case 0:
			f.value, err = r.varint(&pos, end)
		case 1:
			size = 8
		case 2:
			size, err = r.varint(&pos, end)
		case 5:
			size = 4
		default:
			return errRepUnsupported
		}
		if err != nil {
			return err
		}
		if size > uint64(end-pos) {
			return repCorrupt("truncated ONNX field")
		}
		f.start, f.end = pos, pos+int64(size)
		pos = f.end
		if err := visit(f); err != nil {
			return err
		}
	}
	return nil
}

func repLooksONNX(hd []byte) bool {
	return len(hd) >= 2 && hd[0] == 0x08 && hd[1] > 0 && hd[1] < 32
}

func (r *repONNXReader) tensor(f repONNXField) (repModelSpan, error) {
	span := repModelSpan{format: "onnx"}
	var dtype uint64
	var raw, opaque bool
	addDim := func(n uint64) error {
		if len(span.shape) == 32 {
			return errRepLimit
		}
		span.shape = append(span.shape, n)
		return nil
	}
	err := r.fields(f.start, f.end, func(t repONNXField) error {
		switch {
		case t.num == 1 && t.wire == 0:
			return addDim(t.value)
		case t.num == 1 && t.wire == 2:
			for pos := t.start; pos < t.end; {
				dim, err := r.varint(&pos, t.end)
				if err != nil {
					return err
				}
				if err := addDim(dim); err != nil {
					return err
				}
			}
		case t.num == 2 && t.wire == 0:
			dtype = t.value
		case t.num == 8 && t.wire == 2:
			if t.end-t.start > 4096 {
				return errRepLimit
			}
			name := make([]byte, t.end-t.start)
			if err := repReadFullAt(r.src, name, t.start); err != nil {
				return err
			}
			span.name = string(name)
		case t.num == 9 && t.wire == 2:
			opaque = opaque || raw
			raw = true
			span.begin, span.end = t.start, t.end
		case t.num == 13 || t.num == 14 && (t.wire != 0 || t.value != 0):
			opaque = true // No external data is loaded by this adapter.
		case t.num >= 3 && t.num <= 7 || t.num == 10 || t.num == 11:
			opaque = true // Typed repeated payloads keep their original wire bytes.
		}
		return nil
	})
	if err != nil {
		return repModelSpan{}, err
	}
	switch dtype {
	case 1:
		span.dtype, span.width = "F32", 4
	case 10:
		span.dtype, span.width = "F16", 2
	case 16:
		span.dtype, span.width = "BF16", 2
	default:
		opaque = true
	}
	if opaque || !raw || span.name == "" || span.end <= span.begin {
		return repModelSpan{}, nil
	}
	length := uint64(span.end - span.begin)
	elements := uint64(span.width)
	for _, dim := range span.shape {
		if dim == 0 || dim > length/elements {
			return repModelSpan{}, nil
		}
		elements *= dim
	}
	if elements != length {
		return repModelSpan{}, nil
	}
	return span, nil
}

func repONNXLayout(src io.ReaderAt, size int64) ([]repModelSpan, error) {
	r := &repONNXReader{src: src, budget: 1 << 18}
	var spans []repModelSpan
	var position int64
	tensors, graphs := 0, 0
	err := r.fields(0, size, func(f repONNXField) error {
		if f.num != 7 || f.wire != 2 {
			return nil
		}
		graphs++
		if graphs > 1 {
			return errRepUnsupported
		}
		return r.fields(f.start, f.end, func(g repONNXField) error {
			if g.num != 5 || g.wire != 2 {
				return nil
			}
			if tensors++; tensors > 4096 {
				return errRepLimit
			}
			span, err := r.tensor(g)
			if err != nil || span.name == "" {
				return err
			}
			if span.begin < position {
				return repCorrupt("overlapping ONNX tensor spans")
			}
			spans = append(spans, repModelSpan{begin: position, end: span.begin, width: 1}, span)
			position = span.end
			return nil
		})
	})
	if err != nil {
		return nil, err
	}
	if len(spans) == 0 {
		return nil, errRepUnsupported
	}
	return append(spans, repModelSpan{begin: position, end: size, width: 1}), nil
}

func repModelLayout(src io.ReaderAt, size int64) ([]repModelSpan, error) {
	var magic [4]byte
	if err := repReadFullAt(src, magic[:], 0); err != nil {
		return nil, err
	}
	var spans []repModelSpan
	if string(magic[:]) == "GGUF" {
		f, e := repGGParse(src, size, repGGLimits{MaxMeta: 16 << 20, MaxTensors: 4096, MaxKV: 65536, MaxString: 1 << 20})
		if e != nil {
			return nil, e
		}
		for _, seg := range f.Segments() {
			s := repModelSpan{begin: seg.Begin, end: seg.End, width: 1}
			if seg.Tensor >= 0 {
				t := &f.Tensors[seg.Tensor]
				g := repGGGeom[t.Type]
				s.name, s.format, s.dtype, s.width = t.Name, "gguf", g.Name, int(g.Bytes)
				s.shape = append([]uint64(nil), t.Dims...)
			}
			spans = append(spans, s)
		}
	} else {
		f, e := repSTParse(src, size, repSTOptions{MaxHeader: 16 << 20, MaxTensors: 4096, MaxDims: 32})
		switch {
		case e != nil && repLooksONNX(magic[:]):
			spans, e = repONNXLayout(src, size)
			if e != nil {
				return nil, e
			}
		case e != nil:
			return nil, e
		default:
			for _, seg := range f.Segments() {
				s := repModelSpan{begin: seg.Off, end: seg.Off + seg.Len, width: 1}
				if seg.Kind == "tensor" {
					t, ok := f.Lookup(seg.Name)
					if !ok {
						return nil, errRepCorrupt
					}
					s.name, s.format, s.dtype, s.width = t.Name, "safetensors", t.DType, max(1, t.Bits/8)
					for _, v := range t.Shape {
						s.shape = append(s.shape, uint64(v))
					}
				}
				spans = append(spans, s)
			}
		}
	}
	var pos int64
	for _, s := range spans {
		if s.begin != pos || s.end < s.begin || s.end > size || s.width < 1 || s.width > 4096 || len(s.name) > 4096 {
			return nil, errRepUnsupported
		}
		pos = s.end
	}
	if pos != size {
		return nil, repCorrupt("model layout tiling")
	}
	return spans, nil
}
func repModelKey(s repModelSpan) [32]byte {
	raw, _ := json.Marshal([]any{s.format, s.name, s.dtype, s.shape})
	return sha256.Sum256(raw)
}

// repModelPlaneReader holds one input window and one plane window. The output
// digest is over original plaintext, before XOR/plane transformation. Previous
// tensor bytes are read only through the serialized, bounded model range reader.
type repModelPlaneReader struct {
	src          io.ReaderAt
	base         *repCall
	size, off    int64
	width, elems int
	h            hash.Hash
	out          []byte
	pos          int
}

func (r *repModelPlaneReader) Read(p []byte) (int, error) {
	if len(p) == 0 {
		return 0, nil
	}
	if r.pos == len(r.out) {
		if r.off == r.size {
			return 0, io.EOF
		}
		n := min(int64(r.width*r.elems), r.size-r.off)
		if n <= 0 || n%int64(r.width) != 0 {
			return 0, errRepUnsupported
		}
		raw := make([]byte, int(n))
		if err := repReadFullAt(r.src, raw, r.off); err != nil {
			return 0, err
		}
		r.h.Write(raw)
		if r.base != nil {
			base, e := repMDReadModelRange(r.base, r.off, n)
			if e != nil {
				return 0, e
			}
			if len(base) != len(raw) {
				return 0, errRepMismatch
			}
			for i := range raw {
				raw[i] ^= base[i]
			}
		}
		r.out = repMDPlaneChunks(raw, r.width, r.elems)
		r.pos = 0
		r.off += n
	}
	n := copy(p, r.out[r.pos:])
	r.pos += n
	return n, nil
}
func repModelHops(c *repCall) (int, error) {
	r, e := repMDparseModelRecipe(c.Rep)
	if e != nil {
		return 0, e
	}
	if len(r.Ops) != 1 {
		return 0, errRepUnsupported
	}
	op := r.Ops[0]
	switch op.Tag {
	case repMDopCopy:
		if c.Rep.Members[op.M].Role != repStored {
			return 0, errRepUnsupported
		}
		return 0, nil
	case repMDopPlanes:
		return 1, nil
	case repMDopXORPlanes:
		if c.Rep.Members[op.Base].Role == repStored {
			return 1, nil
		}
		ch, e := c.child(op.Base)
		if e != nil {
			return 0, e
		}
		h, e := repModelHops(ch)
		return h + 1, e
	}
	return 0, errRepUnsupported
}
func (b *repBuilder) modelBase(s repModelSpan) (*repCall, [32]byte, bool) {
	var zero [32]byte
	if b.cat == nil {
		return nil, zero, false
	}
	key := repModelKey(s)
	// Basis selection reads up to eight explicit SHA candidates. Their bytes are
	// XOR inputs; the resulting child must still prove exact through every base.
	// The catalog's canonical identity resolver retains its ambiguity semantics.
	entries := b.cat.idx["k8/w32\x00"+string(key[:])]
	if len(entries) == 0 || len(entries) > 8 {
		return nil, zero, false
	}
	var ids [][32]byte
	seen := map[[32]byte]bool{}
	for _, entry := range entries {
		if !seen[entry.target] {
			seen[entry.target] = true
			ids = append(ids, entry.target)
		}
	}
	sort.Slice(ids, func(i, j int) bool { return bytes.Compare(ids[i][:], ids[j][:]) < 0 })
	var best *repCall
	var bestSHA [32]byte
	bestHops := -1
	for _, id := range ids {
		r, e := b.env.loadRep(id)
		if e != nil || r.Kind != repKindModel || r.Size != s.end-s.begin {
			continue
		}
		c := b.env.call(id, r, 1, nil, nil)
		h, e := repModelHops(c)
		if e != nil || h >= 3 || h <= bestHops {
			continue
		}
		mr, e := repMDparseModelRecipe(r)
		if e != nil || len(mr.Names) != 1 || !strings.HasPrefix(mr.Names[0].Name, repModelDigestHint) {
			continue
		}
		sum, e := decodeHexSHA256(strings.TrimPrefix(mr.Names[0].Name, repModelDigestHint))
		if e != nil {
			continue
		}
		best, bestSHA, bestHops = c, sum, h
	}
	return best, bestSHA, best != nil
}

func (b *repBuilder) encodeModel(src io.ReaderAt, size int64) (*repObject, error) {
	// Reserve one full source pass before writing anything. An optional base pass
	// must fit the existing cumulative inspection budget; otherwise reset to planes.
	if size <= 0 || size > repMaxInspect {
		return nil, errRepLimit
	}
	if e := b.budget.inspect(size); e != nil {
		return nil, e
	}
	spans, e := repModelLayout(src, size)
	if e != nil {
		return nil, e
	}
	out := &repObject{Kind: repKindModel, Size: size}
	var ops []repMDModelOp
	pairs := map[string][32]byte{}
	addStored := func(id [32]byte, n int64) {
		m := len(out.Members)
		out.Members = append(out.Members, repMember{Role: repStored, SHA: id, Size: n})
		ops = append(ops, repMDModelOp{Tag: repMDopCopy, M: m})
	}
	for _, span := range spans {
		n := span.end - span.begin
		if n == 0 {
			continue
		}
		section := io.NewSectionReader(src, span.begin, n)
		if span.name == "" {
			if e := b.putCDC(section, addStored); e != nil {
				return nil, e
			}
			continue
		}
		w := span.width
		if n%int64(w) != 0 {
			return nil, errRepUnsupported
		}
		elems := max(1, repModelWindow/w)
		base, baseSHA, found := b.modelBase(span)
		if found {
			if n > repMaxInspect-b.budget.inspected {
				base = nil
				found = false
			} else if e := b.budget.inspect(n); e != nil {
				return nil, e
			}
		}
		rd := &repModelPlaneReader{src: section, base: base, size: n, width: w, elems: elems, h: sha256.New()}
		rid, e := b.putStream(rd, n)
		if e != nil {
			return nil, e
		}
		if rd.off != n || rd.pos != len(rd.out) {
			return nil, errRepShort
		}
		var plainSHA [32]byte
		rd.h.Sum(plainSHA[:0])
		child := &repObject{Kind: repKindModel, Size: n}
		op := repMDModelOp{Tag: repMDopPlanes, W: w, E: elems, Name: repModelDigestHint + hex.EncodeToString(plainSHA[:])}
		if found {
			child.Members = append(child.Members, repMember{Role: repDerived, SHA: baseSHA, Size: n, Child: base.ID})
			op.Tag = repMDopXORPlanes
			op.Base = 0
		}
		op.Res = len(child.Members)
		child.Members = append(child.Members, repMember{Role: repStored, SHA: rid, Size: n})
		if w == 1 && !found {
			op.Tag = repMDopCopy
			op.M = op.Res
		}
		child.Recipe = repMDBuildModelRecipe([]repMDModelOp{op})
		cid, e := b.finishRep(child)
		if e != nil {
			return nil, e
		}
		m := len(out.Members)
		out.Members = append(out.Members, repMember{Role: repDerived, SHA: plainSHA, Size: n, Child: cid})
		ops = append(ops, repMDModelOp{Tag: repMDopCopy, M: m, Name: span.name})
		key := repModelKey(span)
		pairs[string(key[:])] = cid
		if len(ops) > repMDmaxOps {
			return nil, errRepLimit
		}
	}
	out.Recipe = repMDBuildModelRecipe(ops)
	if len(pairs) > 0 {
		index, count, e := repBuildIndex(32, pairs)
		if e != nil {
			return nil, e
		}
		id, e := b.putBlob(index)
		if e != nil {
			return nil, e
		}
		out.Indexes = []repIndex{{KeyWidth: 32, Count: count, Ref: id, Owns: true}}
	}
	return out, nil
}

// Aggregate replay bounds are independent of emitted size: repeated empty
// children must not evade depth/output limits. Atomics cover Model pipe readers.
// Each call owns a budget; repEnv remains safe for independent reconstructions.
type repDecodeWork struct {
	steps, metadata, bytes atomic.Int64
	maxBytes               int64
}

func newRepDecodeWork(size int64) *repDecodeWork {
	// Saturate instead of wrapping for a structurally valid enormous declaration.
	limit := int64(math.MaxInt64)
	if size <= (math.MaxInt64-(64<<20))/16 {
		limit = size*16 + (64 << 20)
	}
	return &repDecodeWork{maxBytes: limit}
}
func (w *repDecodeWork) step(n int64) error {
	if n < 0 || w.steps.Add(n) > 1<<20 {
		return fmt.Errorf("%w: aggregate decoder steps", errRepLimit)
	}
	return nil
}
func (w *repDecodeWork) enter(r *repObject) error {
	if err := w.enterMetadata(r); err != nil {
		return err
	}
	return w.reserveBytes(r.Size)
}
func (w *repDecodeWork) enterMetadata(r *repObject) error {
	if err := w.step(1); err != nil {
		return err
	}
	n := int64(len(r.Recipe)) + int64(len(r.Members))*64 + int64(len(r.Indexes))*64
	if w.metadata.Add(n) > 64<<20 {
		return fmt.Errorf("%w: aggregate decoder metadata", errRepLimit)
	}
	return nil
}
func (w *repDecodeWork) reserveBytes(n int64) error {
	// CAS reservation avoids overflow even for a MaxInt64 declaration.
	for {
		old := w.bytes.Load()
		if n < 0 || n > w.maxBytes-old {
			return fmt.Errorf("%w: aggregate decoded bytes", errRepLimit)
		}
		if w.bytes.CompareAndSwap(old, old+n) {
			return nil
		}
	}
}

func (c *repCall) decodeWork() *repDecodeWork {
	if c.work == nil {
		c.work = newRepDecodeWork(c.Rep.Size)
	}
	return c.work
}

// Publication inspects every derived kind before the durable capability floor.
func (s *Store) repPublicationFloor(r *repRoot) (int, error) {
	src := s.newRepSource(r.Descs, nil)
	defer src.close()
	env := &repEnv{Src: src, Limits: repProdLimits}
	reach, err := env.reachable(r.Rep)
	if err != nil {
		return 0, err
	}
	return repFloorOf(env, reach)
}

// repRootHard reports whether a representation closure holds a Parquet or SST recipe that needs the
// exact Brotli or LZ4 replay (the recipe's first byte is the hard version).
func (s *Store) repRootHard(r *repRoot) (hard, stream bool, err error) {
	src := s.newRepSource(r.Descs, nil)
	defer src.close()
	env := &repEnv{Src: src, Limits: repProdLimits}
	reach, err := env.reachable(r.Rep)
	if err != nil {
		return false, false, err
	}
	for id, role := range reach.Role {
		if role != repDepRep {
			continue
		}
		obj, err := env.loadRep(id)
		if err != nil {
			return false, false, err
		}
		if len(obj.Recipe) > 0 && (obj.Kind == repKindParquet && obj.Recipe[0] >= repPQrecipeVersionHard || obj.Kind == repKindSST && obj.Recipe[0] == repSSrecipeVersionHard) {
			hard = true
			stream = stream || obj.Kind == repKindParquet && obj.Recipe[0] == repPQrecipeVersionStream
		}
	}
	return hard, stream, nil
}

// repFloorOf is the store-format level the representation closure reach describes
// requires. A builder that has just walked the closure passes its own result in
// rather than walking it a second time.
func repFloorOf(env *repEnv, reach *repReach) (int, error) {
	floor := storeFormatVersionRepresentations
	for id, role := range reach.Role {
		if role != repDepRep {
			continue
		}
		obj, err := env.loadRep(id)
		if err != nil {
			return 0, err
		}
		switch obj.Kind {
		case repKindConcat, repKindCAR, repKindSQLite, repKindGit, repKindMerkle, repKindGzip, repKindZstd:
		case repKindModel:
			floor = max(floor, storeFormatVersionModel)
		case repKindSST, repKindParquet:
			floor = max(floor, storeFormatVersionStructured)
		case repKindDEX, repKindCLR:
			floor = max(floor, storeFormatVersionManaged)
		default:
			return 0, fmt.Errorf("%w: capability kind %d", errRepUnsupported, obj.Kind)
		}
	}
	if floor > storeFormatVersionSupported {
		return 0, fmt.Errorf("%w: required capability floor %d", errRepUnsupported, floor)
	}
	return floor, nil
}

// ---- Mechanically extracted structured codec cores from immutable #81 ---- -----------
// Mechanically extracted from zeros3-z3 codec sources; see provenance manifest.

// Port source: zeros3-z3/sstz3/block.go
// Layout describes how a decoded block frames its entries. A block that matches the
// table's derived layout (restarts at every RestartInterval-th entry, every
// non-restart entry sharing the maximal prefix with its predecessor) needs no
// stored layout at all.
type repSSLayout struct {
	Entries    int
	RestartIdx []int // entry index of every restart
	Shared     []int // shared-prefix length of every entry
	HashIndex  bool  // RocksDB data block hash index flag (unsupported)
}

// Port source: zeros3-z3/sstz3/block.go
// WalkBlock validates a decoded block (entries, restart array, restart count) and
// calls fn for every entry in order with its full key (valid only during the call)
// and value (aliases b). It rejects bad varints, arithmetic overflow, entries or
// restarts outside the payload, a shared length above the previous key's length,
// restarts that are not strictly increasing entry boundaries (the first at 0), and a
// truncated restart array. fn may be nil.
func repSSWalkBlock(b []byte, lim repSSLimits, fn func(i int, key, val []byte) error) (*repSSLayout, error) {
	lim = lim.norm()
	if len(b) < 4 {
		return nil, repSScorrupt("block of %d bytes", len(b))
	}
	nr := binary.LittleEndian.Uint32(b[len(b)-4:])
	l := &repSSLayout{}
	if nr&(1<<31) != 0 { // RocksDB: data-block hash index appended after the restarts
		l.HashIndex = true
		return l, repSSunsupported("data block hash index")
	}
	if nr == 0 || uint64(nr) > uint64(len(b)-4)/4 || int64(nr) > int64(lim.MaxEntries) {
		return nil, repSScorrupt("restart count %d in a block of %d bytes", nr, len(b))
	}
	payload := len(b) - 4 - 4*int(nr)
	if payload < 0 {
		return nil, repSScorrupt("restart array exceeds the block")
	}
	restarts := make([]uint32, nr)
	for i := range restarts {
		restarts[i] = binary.LittleEndian.Uint32(b[payload+4*i:])
		if int64(restarts[i]) > int64(payload) || (i > 0 && restarts[i] <= restarts[i-1]) || (i == 0 && restarts[i] != 0) {
			return nil, repSScorrupt("restart %d offset %d (payload %d)", i, restarts[i], payload)
		}
	}
	var key []byte
	pos, ri := 0, 0
	for pos < payload {
		isRestart := ri < len(restarts) && int(restarts[ri]) == pos
		if ri < len(restarts) && int(restarts[ri]) < pos {
			return nil, repSScorrupt("restart %d is inside an entry", ri)
		}
		shared, n1 := binary.Uvarint(b[pos:payload])
		if n1 <= 0 {
			return nil, repSScorrupt("shared length varint at %d", pos)
		}
		nonShared, n2 := binary.Uvarint(b[pos+n1 : payload])
		if n2 <= 0 {
			return nil, repSScorrupt("non-shared length varint at %d", pos)
		}
		vlen, n3 := binary.Uvarint(b[pos+n1+n2 : payload])
		if n3 <= 0 {
			return nil, repSScorrupt("value length varint at %d", pos)
		}
		hdr := pos + n1 + n2 + n3
		if shared > uint64(len(key)) || (isRestart && shared != 0) {
			return nil, repSScorrupt("shared length %d with previous key of %d at %d", shared, len(key), pos)
		}
		if nonShared > uint64(lim.MaxRecordBytes) || vlen > uint64(lim.MaxRecordBytes) ||
			nonShared > uint64(payload-hdr) || vlen > uint64(payload-hdr)-nonShared {
			return nil, repSScorrupt("entry at %d exceeds the block", pos)
		}
		if l.Entries >= lim.MaxEntries {
			return nil, repSSErrLimit
		}
		if isRestart {
			l.RestartIdx = append(l.RestartIdx, l.Entries)
			ri++
		}
		key = append(key[:shared], b[hdr:hdr+int(nonShared)]...)
		val := b[hdr+int(nonShared) : hdr+int(nonShared)+int(vlen)]
		l.Shared = append(l.Shared, int(shared))
		if fn != nil {
			if err := fn(l.Entries, key, val); err != nil {
				return nil, err
			}
		}
		l.Entries++
		pos = hdr + int(nonShared) + int(vlen)
	}
	if pos != payload {
		return nil, repSScorrupt("entries end at %d, payload ends at %d", pos, payload)
	}
	if ri != len(restarts) && !(payload == 0 && nr == 1) {
		return nil, repSScorrupt("%d restarts do not sit on entry boundaries", len(restarts)-ri)
	}
	if l.Entries == 0 && (nr != 1 || payload != 0) {
		return nil, repSScorrupt("empty block with %d restarts", nr)
	}
	return l, nil
}

// Port source: zeros3-z3/sstz3/block.go
// derives reports whether the block's framing equals the one derived from the
// table's restart interval r and maximal prefix sharing, given the entries' keys.
// keys is called with every entry index in order.
func (l *repSSLayout) derivesFrom(r int, keyAt func(i int) []byte) bool {
	if r <= 0 {
		return false
	}
	for k, idx := range l.RestartIdx {
		if idx != k*r {
			return false
		}
	}
	if len(l.RestartIdx) != (l.Entries+r-1)/r && l.Entries > 0 {
		return false
	}
	var prev []byte
	for i := 0; i < l.Entries; i++ {
		k := keyAt(i)
		want := 0
		if i%r != 0 {
			want = repSScommonPrefix(prev, k)
		}
		if l.Shared[i] != want {
			return false
		}
		prev = k
	}
	return true
}

// Port source: zeros3-z3/sstz3/block.go
func repSScommonPrefix(a, b []byte) int {
	n := min(len(a), len(b))
	i := 0
	for i < n && a[i] == b[i] {
		i++
	}
	return i
}

// Port source: zeros3-z3/sstz3/block.go
// BlockWriter rebuilds the exact bytes of a decoded block from full keys and values.
type repSSBlockWriter struct {
	buf      []byte
	restarts []uint32
	prev     []byte
	n        int
}

// Port source: zeros3-z3/sstz3/block.go
// Reset starts a new block, reusing buffers.
func (w *repSSBlockWriter) Reset() {
	w.buf, w.restarts, w.prev, w.n = w.buf[:0], w.restarts[:0], w.prev[:0], 0
}

// Port source: zeros3-z3/sstz3/block.go
// Add appends one entry. restart forces a restart point; shared < 0 means the maximal
// common prefix with the previous key (0 at a restart); otherwise the stored value is
// used and must not exceed the previous key's length.
func (w *repSSBlockWriter) Add(key, val []byte, restart bool, shared int) error {
	if restart {
		w.restarts = append(w.restarts, uint32(len(w.buf)))
		shared = 0
	} else if shared < 0 {
		shared = repSScommonPrefix(w.prev, key)
	}
	if shared > len(w.prev) || shared > len(key) {
		return repSScorrupt("shared length %d above key lengths %d/%d", shared, len(w.prev), len(key))
	}
	if int64(len(w.buf))+int64(len(key))+int64(len(val))+30 > math.MaxUint32 {
		return repSSErrLimit
	}
	w.buf = binary.AppendUvarint(w.buf, uint64(shared))
	w.buf = binary.AppendUvarint(w.buf, uint64(len(key)-shared))
	w.buf = binary.AppendUvarint(w.buf, uint64(len(val)))
	w.buf = append(w.buf, key[shared:]...)
	w.buf = append(w.buf, val...)
	w.prev = append(w.prev[:0], key...)
	w.n++
	return nil
}

// Port source: zeros3-z3/sstz3/block.go
// Finish appends the restart array and count and returns the block bytes (valid until
// the next Reset).
func (w *repSSBlockWriter) Finish() []byte {
	if len(w.restarts) == 0 { // an empty block still has one restart at 0
		w.restarts = append(w.restarts, 0)
	}
	for _, r := range w.restarts {
		w.buf = binary.LittleEndian.AppendUint32(w.buf, r)
	}
	w.buf = binary.LittleEndian.AppendUint32(w.buf, uint32(len(w.restarts)))
	return w.buf
}

// Port source: zeros3-z3/sstz3/decode.go
// Getter fetches a component by digest. The caller is responsible for checking the
// bytes against the digest and the declared length before returning them.
type repSSGetter func(id repSSID) ([]byte, error)

// Port source: zeros3-z3/sstz3/decode.go
// RangeStats reports what a ranged decode touched.
type repSSRangeStats struct {
	Blocks     int // data blocks rebuilt
	Components int // component fetches
	Bytes      int64
	Records    int64 // records parsed (including those skipped to reach the first block)
}

// Port source: zeros3-z3/sstz3/decode.go
type repSScursor struct {
	rec      *repSSRecipe
	get      repSSGetter
	lim      repSSLimits
	S        int
	g        int    // current group
	left     uint32 // records left in the group
	comp     [3][]byte
	rix      int64 // global record index
	st       *repSSRangeStats
	started  bool
	nextAuto bool
}

// Port source: zeros3-z3/sstz3/decode.go
func (c *repSScursor) load(g int) error {
	if g >= len(c.rec.Groups) {
		return repSSrecipeErr("records beyond the last group")
	}
	for s := 0; s < c.S; s++ {
		b, err := c.get(c.rec.Digests[g*c.S+s])
		if err != nil {
			return err
		}
		if int64(len(b)) > c.lim.MaxDecoded {
			return repSSErrLimit
		}
		c.comp[s] = b
		c.st.Components++
		c.st.Bytes += int64(len(b))
	}
	c.g, c.left, c.started = g, c.rec.Groups[g], true
	return nil
}

// Port source: zeros3-z3/sstz3/decode.go
func repSStakeLen(b *[]byte, max int64) ([]byte, error) {
	n, k := binary.Uvarint(*b)
	if k <= 0 || n > uint64(max) || n > uint64(len(*b)-k) {
		return nil, repSScorrupt("record length in a component")
	}
	v := (*b)[k : k+int(n)]
	*b = (*b)[k+int(n):]
	return v, nil
}

// Port source: zeros3-z3/sstz3/decode.go
// next returns the next record's user key, trailer and value.
func (c *repSScursor) next() (ukey []byte, trailer uint64, val []byte, err error) {
	if !c.started || c.left == 0 {
		if c.started {
			for s := 0; s < c.S; s++ {
				if len(c.comp[s]) != 0 {
					return nil, 0, nil, repSScorrupt("group %d has trailing bytes", c.g)
				}
			}
		}
		ng := 0
		if c.started {
			ng = c.g + 1
		}
		if err = c.load(ng); err != nil {
			return
		}
	}
	m := c.lim.MaxRecordBytes
	f := c.rec.Form
	switch f {
	case repSSFormUKV, repSSFormFull:
		if ukey, err = repSStakeLen(&c.comp[0], m); err != nil {
			return
		}
		if f == repSSFormFull {
			if len(c.comp[0]) < 8 {
				return nil, 0, nil, repSScorrupt("truncated trailer")
			}
			trailer = binary.LittleEndian.Uint64(c.comp[0])
			c.comp[0] = c.comp[0][8:]
		}
		val, err = repSStakeLen(&c.comp[0], m)
	case repSSFormKV, repSSFormKTV, repSSFormKVT:
		if ukey, err = repSStakeLen(&c.comp[0], m); err != nil {
			return
		}
		switch f {
		case repSSFormKTV:
			if len(c.comp[0]) < 8 {
				return nil, 0, nil, repSScorrupt("truncated trailer")
			}
			trailer = binary.LittleEndian.Uint64(c.comp[0])
			c.comp[0] = c.comp[0][8:]
		case repSSFormKVT:
			if len(c.comp[2]) < 8 {
				return nil, 0, nil, repSScorrupt("truncated trailer")
			}
			trailer = binary.LittleEndian.Uint64(c.comp[2])
			c.comp[2] = c.comp[2][8:]
		}
		val, err = repSStakeLen(&c.comp[1], m)
	}
	if err != nil {
		return
	}
	if c.rec.Form.trailersInRecipe() {
		if c.rix >= int64(len(c.rec.Trailers)) {
			return nil, 0, nil, repSSrecipeErr("trailer index")
		}
		trailer = c.rec.Trailers[c.rix]
	}
	c.rix++
	c.left--
	c.st.Records++
	return
}

// Port source: zeros3-z3/sstz3/decode.go
// Decode rebuilds the original table from the serialized recipe (head and digests) and
// the components, writing it to w. It reads components lazily in file order and holds
// one group (a few components) and one data block.
func repSSDecode(w io.Writer, recipe []byte, get repSSGetter, lim repSSLimits) error {
	_, err := repSSDecodeRange(w, recipe, get, 0, -1, lim)
	return err
}

// Port source: zeros3-z3/sstz3/decode.go
// DecodeRange writes bytes [off, off+n) of the original table (n < 0: to the end). Only
// the data blocks overlapping the range are rebuilt, and only the groups holding their
// records are fetched; the tail component is fetched only if the range reaches it.
func repSSDecodeRange(w io.Writer, recipe []byte, get repSSGetter, off, n int64, lim repSSLimits) (repSSRangeStats, error) {
	var st repSSRangeStats
	lim = lim.norm()
	rec, err := repSSParseRecipe(recipe, lim)
	if err != nil {
		return st, err
	}
	if off < 0 || off > rec.Size {
		return st, repSSErrLimit
	}
	if n < 0 || n > rec.Size-off {
		n = rec.Size - off
	}
	if n == 0 {
		return st, nil
	}
	end := off + n
	dataEnd := rec.Size - rec.TailLen
	// physical offsets of the blocks
	starts := make([]int64, len(rec.Blocks)+1)
	for i := range rec.Blocks {
		starts[i+1] = starts[i] + int64(rec.Blocks[i].CSize) + repSStrailerLen
	}
	first := sort.Search(len(rec.Blocks), func(i int) bool { return starts[i+1] > off })
	cur := &repSScursor{rec: rec, get: get, lim: lim, S: rec.Form.streams(), st: &st}
	var bw repSSBlockWriter
	var key []byte
	var payload bytes.Buffer
	if rec.Form != repSSFormBlocks && first < len(rec.Blocks) && off < dataEnd && n > 0 {
		var r0 int64
		for i := 0; i < first; i++ {
			r0 += int64(rec.Blocks[i].Entries)
		}
		// locate the group of record r0 and skip to it
		var acc int64
		g := 0
		for g < len(rec.Groups) && acc+int64(rec.Groups[g]) <= r0 {
			acc += int64(rec.Groups[g])
			g++
		}
		if g < len(rec.Groups) {
			if err := cur.load(g); err != nil {
				return st, err
			}
			cur.rix = acc
			for ; acc < r0; acc++ {
				if _, _, _, err := cur.next(); err != nil {
					return st, err
				}
			}
		}
	}
	var written int64
	pos := starts[first]
	lastBlock := -1
	for bi := first; bi < len(rec.Blocks) && pos < end && pos < dataEnd; bi++ {
		bl := &rec.Blocks[bi]
		var raw []byte
		if rec.Form == repSSFormBlocks {
			b, err := get(rec.Digests[bi])
			if err != nil {
				return st, err
			}
			st.Components++
			st.Bytes += int64(len(b))
			if uint64(len(b)) != bl.Decoded {
				return st, repSScorrupt("block %d component has %d bytes, recipe says %d", bi, len(b), bl.Decoded)
			}
			raw = b
		} else {
			bw.Reset()
			r := int(rec.RestartInterval)
			ri := 0
			for i := 0; i < int(bl.Entries); i++ {
				uk, tr, val, err := cur.next()
				if err != nil {
					return st, err
				}
				key = append(append(key[:0], uk...), 0, 0, 0, 0, 0, 0, 0, 0)
				binary.LittleEndian.PutUint64(key[len(uk):], tr)
				restart, shared := false, -1
				if ex := bl.Explicit; ex != nil {
					if ri < len(ex.Restarts) && int(ex.Restarts[ri]) == i {
						restart = true
						ri++
					}
					shared = int(ex.Shared[i])
				} else {
					if r == 0 {
						return st, repSSrecipeErr("restart interval 0")
					}
					restart = i%r == 0
				}
				if err := bw.Add(key, val, restart, shared); err != nil {
					return st, err
				}
			}
			raw = bw.Finish()
		}
		st.Blocks++
		payload.Reset()
		switch bl.Trailer[0] {
		case repSSCompZstd:
			if err := repSSreplayZstdBlock(&payload, bl.Zstd, raw, lim); err != nil {
				return st, err
			}
		case repSSCompLZ4, repSSCompLZ4HC:
			if err := repSSreplayLZ4Block(&payload, bl.LZ4, raw, lim); err != nil {
				return st, err
			}
		case repSSCompNone:
			payload.Write(raw)
		case repSSCompSnappy:
			switch {
			case bl.Pred == repSSPredGo && len(raw) <= repSNMaxPredict:
				payload.Write(repSNEncodeRef(raw))
			case bl.Pred == repSSPredCPP && len(raw) <= repSNMaxPredict:
				payload.Write(repSNEncodeCPP(raw))
			case bl.Pred == repSSPredCPP15 && len(raw) <= repSNMaxPredict:
				payload.Write(repSNEncodeCPP15(raw))
			case bl.Pred != 0:
				return st, repSSrecipeErr("block %d predicted at %d bytes", bi, len(raw))
			default:
				cmds, err := repSSsnappyCmds(bl, int64(len(raw)), lim)
				if err != nil {
					return st, err
				}
				if err := repSNReplay(&payload, raw, cmds); err != nil {
					return st, err
				}
			}
		default:
			return st, repSSrecipeErr("compression type %d", bl.Trailer[0])
		}
		if uint64(payload.Len()) != bl.CSize {
			return st, repSScorrupt("block %d rebuilt to %d bytes, recipe says %d", bi, payload.Len(), bl.CSize)
		}
		payload.Write(bl.Trailer[:])
		b := payload.Bytes()
		lo, hi := max(off, pos)-pos, min(end, pos+int64(len(b)))-pos
		if hi > lo {
			if _, err := w.Write(b[lo:hi]); err != nil {
				return st, err
			}
			written += hi - lo
		}
		pos += int64(len(b))
		lastBlock = bi
	}
	if rec.Form != repSSFormBlocks && lastBlock == len(rec.Blocks)-1 && len(rec.Blocks) > 0 && cur.started {
		// the whole data region was rebuilt: every record of every group must be consumed
		if cur.left != 0 || cur.g != len(rec.Groups)-1 {
			return st, repSScorrupt("%d records left over", cur.left)
		}
		for s := 0; s < cur.S; s++ {
			if len(cur.comp[s]) != 0 {
				return st, repSScorrupt("last group has trailing bytes")
			}
		}
	}
	if end > dataEnd && n > 0 {
		t, err := get(rec.Digests[len(rec.Digests)-1])
		if err != nil {
			return st, err
		}
		st.Components++
		st.Bytes += int64(len(t))
		if int64(len(t)) != rec.TailLen {
			return st, repSScorrupt("tail component has %d bytes, recipe says %d", len(t), rec.TailLen)
		}
		lo := max(off, dataEnd) - dataEnd
		if _, err := w.Write(t[lo : end-dataEnd]); err != nil {
			return st, err
		}
		written += end - dataEnd - lo
	}
	if written != n {
		return st, repSScorrupt("wrote %d of %d bytes", written, n)
	}
	return st, nil
}

// Port source: zeros3-z3/sstz3/doc.go
var (
	// ErrCorrupt reports bytes that violate the table or block format.
	repSSErrCorrupt = errors.New("sstz3: corrupt table")
	// ErrUnsupported reports a well-formed table (or feature) the exact representation
	// does not express; the caller falls back to ordinary CDC.
	repSSErrUnsupported = errors.New("sstz3: unsupported table")
	// ErrLimit reports that a configured bound would be exceeded.
	repSSErrLimit = errors.New("sstz3: limit exceeded")
	// ErrRecipe reports a malformed serialized recipe.
	repSSErrRecipe = errors.New("sstz3: malformed recipe")
)

// Port source: zeros3-z3/sstz3/doc.go
func repSScorrupt(f string, a ...any) error {
	return fmt.Errorf("%w: "+f, append([]any{repSSErrCorrupt}, a...)...)
}

// Port source: zeros3-z3/sstz3/doc.go
func repSSunsupported(f string, a ...any) error {
	return fmt.Errorf("%w: "+f, append([]any{repSSErrUnsupported}, a...)...)
}

// Port source: zeros3-z3/sstz3/doc.go
func repSSrecipeErr(f string, a ...any) error {
	return fmt.Errorf("%w: "+f, append([]any{repSSErrRecipe}, a...)...)
}

// Port source: zeros3-z3/sstz3/doc.go
// Limits bound every parse. The zero value selects the defaults.
type repSSLimits struct {
	MaxBlocks      int   // data blocks per table (default 1<<20)
	MaxBlockBytes  int64 // one stored block payload (default 16 MiB)
	MaxDecoded     int64 // one decompressed block (default 64 MiB)
	MaxEntries     int   // entries per block (default 1<<22)
	MaxMeta        int64 // one metadata block read by Open (default 64 MiB)
	MaxTail        int64 // opaque tail span (default 256 MiB)
	MaxRecordBytes int64 // one key or value (default 64 MiB)
	MaxRecipe      int64 // recipe head bytes (default 256 MiB)
	// Hard admits LZ4 and LZ4HC blocks to analysis; the decoder always replays them.
	Hard bool
}

// Port source: zeros3-z3/sstz3/doc.go
func (l repSSLimits) norm() repSSLimits {
	if l.MaxBlocks <= 0 {
		l.MaxBlocks = 1 << 20
	}
	if l.MaxBlockBytes <= 0 {
		l.MaxBlockBytes = 16 << 20
	}
	if l.MaxDecoded <= 0 {
		l.MaxDecoded = 64 << 20
	}
	if l.MaxEntries <= 0 {
		l.MaxEntries = 1 << 22
	}
	if l.MaxMeta <= 0 {
		l.MaxMeta = 64 << 20
	}
	if l.MaxTail <= 0 {
		l.MaxTail = 256 << 20
	}
	if l.MaxRecordBytes <= 0 {
		l.MaxRecordBytes = 64 << 20
	}
	if l.MaxRecipe <= 0 {
		l.MaxRecipe = 256 << 20
	}
	return l
}

// Port source: zeros3-z3/sstz3/encode.go
// Cutter decides group boundaries from the records alone: Cut is called after every
// record with its user key and value length and returns true to close the group after
// it. A cutter must depend on nothing else (no position in the file, no block
// boundary), so an inserted or removed record moves no other boundary.
type repSSCutter interface {
	Cut(ukey []byte, vlen int) bool
}

// Port source: zeros3-z3/sstz3/encode.go
// HashCutter closes a group after a record with probability (record bytes)/Target,
// decided by a hash of the user key, and unconditionally once the group reaches Max.
type repSSHashCutter struct {
	Target, Max int
	cur         int
}

// Port source: zeros3-z3/sstz3/encode.go
// Cut implements Cutter.
func (c *repSSHashCutter) Cut(ukey []byte, vlen int) bool {
	sz := len(ukey) + vlen + 4
	c.cur += sz
	if c.cur >= c.Max || sz >= c.Target {
		c.cur = 0
		return true
	}
	h := uint64(14695981039346656037)
	for _, b := range ukey {
		h = (h ^ uint64(b)) * 1099511628211
	}
	h ^= h >> 29
	h *= 0xbf58476d1ce4e5b9
	h ^= h >> 32
	if h < uint64(sz)*(math.MaxUint64/uint64(c.Target)) {
		c.cur = 0
		return true
	}
	return false
}

// Port source: zeros3-z3/sstz3/encode.go
// Options configures Encode.
type repSSOptions struct {
	Form   repSSForm
	Cutter repSSCutter // nil: one group per data block
	Limits repSSLimits
	// NoPredict forces explicit Snappy command recipes (measurement only).
	NoPredict bool
}

// Port source: zeros3-z3/sstz3/encode.go
// Emit receives every component Encode produces, once per occurrence (the caller
// deduplicates by id). class is "block", "group", "keys", "vals", "trl" or "tail". The
// bytes are only valid during the call.
type repSSEmit func(class string, id repSSID, data []byte) error

// Port source: zeros3-z3/sstz3/encode.go
