// Port source: zeros3-z3/dexz3/dex.go
func (l repDXLimits) norm() repDXLimits {
	d := func(v *int, x int) {
		if *v <= 0 {
			*v = x
		}
	}
	if l.MaxFile <= 0 {
		l.MaxFile = 512 << 20
	}
	d(&l.MaxStrings, 4<<20)
	d(&l.MaxIDs, 1<<20)
	d(&l.MaxMap, 64)
	d(&l.MaxStrLen, 1<<20)
	d(&l.MaxLEB, 5)
	d(&l.MaxCodeUnit, 1<<20)
	d(&l.MaxTries, 1<<16)
	d(&l.MaxHandlers, 1<<16)
	d(&l.MaxMembers, 1<<18)
	d(&l.MaxSlots, 64<<20)
	d(&l.MaxDepth, 32)
	d(&l.MaxDebugOps, 1<<20)
	d(&l.MaxItems, 8<<20)
	return l
}

